  const cards = Object.freeze([...heroes.map(c => ({ ...c, type: 'hero' })), ...weaponCards.map(c => ({ ...c, type: 'weapon', modifiers: c.modifiers || { weaponDamageMultiplier: 1.1 } }))]
    .map(card => Object.freeze({ ...card, modifiers: Object.freeze({ ...card.modifiers }) })));
  const byId = new Map(cards.map(card => [card.id, card]));
  if (byId.size !== cards.length) throw new Error('cards.js: powtórzone id');
  for (const card of cards) if (card.type === 'weapon' && !window.MuseumWeapons?.has(card.weapon)) throw new Error('cards.js: karta broni bez broni: ' + card.id);
  window.MuseumCards = Object.freeze({
    get(id) { return byId.get(id) || null; },
    all() { return cards; },
    heroes() { return cards.filter(card => card.type === 'hero'); },
    weaponCards() { return cards.filter(card => card.type === 'weapon'); }
  });
